/**
 * Central catalogue of the marketing imagery used across the landing pages.
 *
 * Every entry points at a SELF-HOSTED copy under /public/images (generated by
 * `node apps/web/scripts/fetch-images.mjs`), with its attribution metadata kept
 * alongside so we stay compliant with the source licences (Wikimedia CC BY-SA
 * and Unsplash).
 *
 * ── How to switch images ────────────────────────────────────────────────────
 * The active image is `HERO_IMAGE` / `TRUST_IMAGE`. They are set to the first
 * entry of their array. To try a different candidate, change the index:
 *
 *     export const HERO_IMAGE  = HERO_IMAGES[1];  // switch to the Mile 12 market
 *     export const TRUST_IMAGE = TRUST_IMAGES[2]; // switch to "neighbors on a bench"
 *
 * All candidates are already downloaded locally, so switching is instant and
 * keeps the site free of external image dependencies.
 */

export interface SiteImage {
  /** Local path under /public (self-hosted, WebP). */
  src: string;
  alt: string;
  /** Human-readable name for docs / pickers. */
  label: string;
  /** Attribution text shown under the image. */
  credit: string;
  /** Link to the photographer / source page. */
  creditUrl: string;
  /** object-position focal point for object-cover crops (defaults to center). */
  position?: string;
  /** Device-specific framing for narrow (mobile) screens. */
  mobile?: {
    /** Tailwind aspect-ratio utility for the mobile container, e.g. "16/10". */
    aspectRatio?: string;
    /** Focal-point override for the mobile crop. */
    position?: string;
  };
}

