/** Safe indexed access so the active image is always typed as defined. */
function at<T>(list: T[], index: number): T {
  const item = list[index] ?? list[0];
  if (!item) throw new Error("Image list must not be empty.");
  return item;
}

/** Active image for each slot — change the index to pick a different one. */
export const HERO_IMAGE = at(HERO_IMAGES, 0);
export const TRUST_IMAGE = at(TRUST_IMAGES, 2);
